#include <Wire.h>
#include <BH1750.h>

BH1750 lightMeter;
const int relayPin = 2;

void setup() {
  Serial.begin(9600);
  Wire.begin();
  lightMeter.begin();
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW);
}

void loop() {
  float lux = lightMeter.readLightLevel();
  Serial.print("Освещённость: ");
  Serial.print(lux);
  Serial.println(" лк");

  if (lux > 300) {
    digitalWrite(relayPin, LOW);   // отключить лампу
  } else {
    digitalWrite(relayPin, HIGH);  // включить лампу
  }

  delay(3000); // вывод каждые 3 секунды
}
